#!/usr/bin/env python3
"""Generate the navigation chapter and map atlas from audited measurements."""
import argparse
import json
import os
import re
from pathlib import Path
import subprocess
import tempfile
import numpy as np
import pandas as pd
from analyze import HERE,ROOT,METHODS,LABELS,digest
from study import read_manifest

DEST=ROOT/'docs/experiments'
LABELS={key:value.replace('≈',r'$\approx$') for key,value in LABELS.items()}
def num(v,d=2):return '—' if pd.isna(v) else f'{v:.{d}f}'
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |',*['| '+' | '.join(map(str,row))+' |' for row in rows]])+'\n'
def figure(name,caption):return f'![{caption}](navigation_figures/{name}.png){{width=100%}}\n'
def header(title):return f'''---
title: "{title}"
author: "Incremental MeshA* — воспроизводимый экспериментальный артефакт"
date: "Ноябрь 2026"
lang: ru-RU
documentclass: article
fontsize: 10pt
geometry: margin=18mm
mainfont: DejaVu Serif
sansfont: DejaVu Sans
monofont: DejaVu Sans Mono
colorlinks: true
toc: true
---
'''
def pdf(markdown,target):
    cache=Path('/tmp/ima_navigation_fontcache');cache.mkdir(exist_ok=True)
    with tempfile.NamedTemporaryFile(mode='w',encoding='utf8',suffix='.md') as tmp:
        tmp.write(markdown.replace('.png){width=','.pdf){width='));tmp.flush()
        subprocess.run(['pandoc',tmp.name,'--resource-path='+str(DEST),'--pdf-engine=xelatex','--include-in-header=layout.tex','-o',target],cwd=DEST,check=True,env={**os.environ,'XDG_CACHE_HOME':str(cache)})

def build(directory,make_pdf=True,controls_directory=None):
    ad=directory/'analysis';a=json.loads((ad/'analysis.json').read_text());assert a['status']=='passed' and a['source_sha256']==digest(HERE/'analyze.py')
    figs=json.loads((ad/'figures.json').read_text());assert figs['analysis_sha256']==digest(ad/'analysis.json') and figs['source_sha256']==digest(HERE/'figures.py')
    for p,sha in figs['files'].items():assert digest(ROOT/p)==sha
    m=read_manifest();contexts={}
    for r in m['records']:
        selected=set(r['selected_cases'])
        for c in json.loads((ROOT/r['contexts']).read_text())['cases']:
            if c['id'] in selected:contexts[c['id']]=c
    e=pd.read_csv(ad/'episode_metrics.csv');s=pd.read_csv(ad/'map_summary.csv');static=pd.read_csv(ad/'static_radius.csv');pairs=pd.read_csv(ad/'map_pairs.csv');dp=pd.read_csv(ad/'dynamic_pairs.csv')
    prior=pd.read_csv(ad/'prior_by_map.csv');out=[];atlas=[];add=out.append
    control_front_path=(controls_directory or ROOT/'cpp/navigation_controls/results/full').resolve()/'analysis/analysis.json'
    control_front=json.loads(control_front_path.read_text());assert control_front['status']=='passed'
    control_points=pd.read_csv(control_front_path.parent/'parameter_pairs.csv')
    control_wins=control_points[control_points.method.eq('md_astar')&control_points.baseline.eq('octile_reuse')&control_points.paired_online.eq(2)&control_points.online_min_speedup.ge(1.1)]
    point_text='; '.join(f'{r.map}: (k,cr) = ({int(r.k)},{int(r.cr)})' for r in control_wins.itertuples()) or 'нет'
    control_maps=pd.read_csv(control_front_path.parent/'map_pairs.csv');control_maps=control_maps[control_maps.method.eq('md_astar')&control_maps.baseline.eq('octile_reuse')&control_maps.online_speedup.notna()]
    assert len(control_wins)==control_front['md_octile_wins_10pct_both_roots']
    add('# Раскрытие карты и глобальная динамика при n = k')
    add(f'''Новая серия проверяет все 15 реализаций на замкнутых проездах к неизменной цели. Заморожено {len(contexts):,} конфигураций: {m['static_cases']} статических и {m['dynamic_cases']} динамических. Выполнено **{a['timed_runs']:,} измеряемых проездов**, ещё **{a['memory_runs']:,} отдельных проездов для памяти**, проверено **{a['planner_calls']:,} вызовов планировщика**. Предыдущие серии сохраняют собственные времена и протокол; их нельзя объединять с этой серией в один временной рейтинг.

Полный атлас всех карт и параметров: [navigation_by_map.pdf](navigation_by_map.pdf). Численные таблицы со всеми 15 методами находятся в каталоге `cpp/navigation_sweeps/results/full/analysis/`:

- `episode_metrics.csv`: отдельные конфигурации и методы;
- `static_radius.csv`: карты и радиусы раскрытия;
- `dynamic_parameters.csv`: карты, k/cr и методы;
- `map_summary.csv`: полнота, время и работа по картам;
- `map_pairs.csv`: парные сравнения по картам;
- `dynamic_pairs.csv`: парные сравнения по k/cr;
- `work_by_observed_changes.csv`: нагрузка фактических пакетов.

Предыдущие результаты по картам вынесены также в [prior_by_map.csv](prior_by_map.csv).''')
    add('В этой новой серии скорость больше 1 выгодна кандидату. Если не указано иное, ускорения агрегируются геометрическим средним отношений времени по общим допустимым конфигурациям, после медианы повторов внутри конфигурации. Предыдущие серии сохраняют свои определения агрегаторов. Число допустимых пар и полнота всегда рассматриваются вместе с отношением времени.')
    add(f"Дополнительный контроль с более сильным обычным Octile A* reuse ограничивает общий вывод о MD-A*: online-выигрыш минимум 10% на каждом из двух корней получен на **{control_front['md_octile_wins_10pct_both_roots']} из {control_front['md_octile_eligible_points']} сопоставимых точек** карта/k/cr. Выигрышные точки: {point_text}. По геометрическому среднему online-отношений на допустимых опорных конфигурациях MD уступает этому бейзлайну на **{int(control_maps.online_speedup.lt(1).sum())}/{len(control_maps)} карт**. Поэтому таблицы выигрыша над D* lattice ниже показывают конкретную область применимости; универсальное преимущество MD не подтверждено. Подробный пятисторонний контроль и его отдельные времена приведены далее.")
    highlight_position=len(out)
    add('## Протокол и сопоставимость')
    add(r'''В статической серии использованы все шесть прежних car16-карт и те же два корня на карту. До наблюдения все клетки считаются свободными. Квадратный сенсор без окклюзии раскрывает радиус **8, 16, 32 или 64 клетки** перед каждым движением. Агент выполняет один примитив и перепланирует, когда изменились известные стоимости; иначе следует сохранённому суффиксу. Цель, включая курс, неизменна. Лимит — 512 выполненных примитивов.

В динамической серии карта полностью известна в начале. Через каждые **k = 2, 4, 8, 16, 32, 64 выполненных движения** происходят изменения по всей карте. Видимость **n = k**, как задано пользователем. Для **cr = 1%, 5%, 10%, 15%, 20%, 30%** целевое число обменов в одном направлении равно $\lfloor N\,cr/200+0.5\rfloor$, где $N$ — все клетки, включая препятствия. Из **дофазных** свободного и занятого пулов выбирается одинаковое число клеток; новая блокировка не может тут же открыться. Текущая клетка и клетка цели защищены. Число обменов ограничено меньшим доступным пулом. Плотность препятствий сохраняется точно, а фактический $cr=100(B+O)/N$ записан отдельно от запрошенного. При отсутствии фаз доставлено ноль изменений; фактический cr фазы не определён.

Наблюдения происходят перед каждым движением. Поэтому между глобальными фазами тоже могут появляться новые вызовы планировщика: агент обнаруживает ранее произошедшие правки в новой части сенсорной области. Число фаз не равно числу ремонтов; обе величины и реальные размеры наблюдённых пакетов приведены отдельно.

Полный набор из **36 сочетаний k/cr** выполнен на шести полных grid8-картах и четырёх прежних случайных картах 50×50 с плотностями около 10/20/30/40%. Дополнительная динамическая адаптация к car16 выполнена на всех шести картах, но только на четырёх опорных точках, заданных до измерений: **(2,5), (8,10), (32,20), (64,30)**. Это отдельный срез, а не полный car16-перебор; подготовленные остальные car16-входы сохранены, но не считаются измеренными. Для grid8 взяты новые два корня; на картах со стороной не меньше 128 начальное расстояние Чебышёва составляет 144–260 клеток, а эталонный путь — не более 400 шагов. Поэтому успешный проезд на этих картах обязательно переживает как минимум две фазы при k = 64. Малые карты выделяются как диагностика коротких маршрутов. Лимиты: 384 примитива car16 и 512 шагов grid8.

Для grid8 глубина видимости n точно равна шару Чебышёва: диагонали имеют стоимость $\sqrt2$, проверяется клетка назначения, срезание углов разрешено, как в прежних реализациях. Для car16 это **адаптация** протокола: видны клетки коллизионных следов всех дуг, чьи начала достижимы менее чем за n примитивов на свободной бесконечной решётке; затем область обрезается границами карты. Это не квадрат радиуса n и не сенсор с окклюзией. Точная область предвычислена отдельно для каждого курса. Приведённый протокол воспроизводит семейство экспериментов MPGAA* (Hernández, Asín, Baier, AAAI 2015), но не заявляется точной репликацией их реализации или численных результатов.

Все методы используют общие случайные приоритеты клеток по фазам, не зависящие от k/cr и метода. При разных маршрутах защита текущей клетки может изменить глобальную карту. Это **сравнение замкнутых политик**, а не строго одинаковая последовательность запросов. Ранжирование по времени трактуется совместно с успехом и выполненной работой. Прежний replay на одинаковых снимках остаётся отдельным контролем. Из-за n = k нельзя независимо приписать эффект только частоте изменений или только видимости.

Все статические конфигурации имеют три повтора. В grid8-динамике выполнен один полный проход, а четыре заранее заданные точки **(k, cr) = (2, 5), (8, 10), (32, 20), (64, 30)** имеют по три повтора. В car16-динамике выполнены только эти четыре точки, каждая с тремя повторами. Это позволяет полностью покрыть запрошенный grid-протокол, но единичные малые временные различия нельзя считать устойчивым превосходством. Отдельный проход памяти выполнен для всей статической серии и этих четырёх точек динамики на обеих моделях. Все измерения последовательны, порядок методов в повторе рандомизирован.

Параметры поисковых ядер сохранены из репозитория. В частности, Mesh/ParallA* выполняет **100 раскрытий mesh на одно раскрытие LBA*** и возвращает первый найденный ответ. Этот внутренний параметр не является интервалом изменения карты k. Когда mesh-ветвь не помогает, такая диспетчеризация может существенно увеличить работу до срабатывания LBA*-ветви. Числа относятся к этой конфигурации реализации; отдельная настройка соотношения на каждой карте не выполнялась.

Время эпизода — конструктор планировщика плюс все его вызовы; online — вызовы после начального плана. Общие подготовка модели, предвычисление сенсора, изменение мира, сенсор и эталонные проверки исключены из таймера поиска. В CSV отдельно приведены сенсор и сумма поиска с сенсором. Память — пик запрошенных байтов динамического размещения планировщика и текущего пути; общие модель/календарь/мир исключены. Это не RSS. Дефолтный предел — 1 млн раскрытий на запрос; все остановки сохранены.

Планировщик конструируется до первого наблюдения. В неизвестной статической карте первое наблюдение передаётся ему как пакет блокировок исходно свободной карты; начальный вызов включает обработку этого пакета. Поэтому полное время нельзя выдавать за чистое преимущество ремонта. В динамике исходная карта известна целиком и начальный пакет пуст. Альтернативная инициализация планировщика уже после первого наблюдения здесь не измерялась; начальный и online-поиск сохранены отдельно.

После каждого планирования вне таймера выполняется LBA* по текущей карте убеждений, проверяется достижимость, стоимость и геометрическая допустимость ответа. Точные методы должны совпасть по стоимости с допуском $10^{-6}$; Mesh/ParallA* допускает удлинение пути. Если в убеждениях пути нет, отдельно проверяется истинная карта. Такая остановка не считается ошибкой поиска: изменения происходят только после движений, и неподвижный агент не получит следующей фазы. В таблицах она различается с истинной недостижимостью.''')
    add(f'''Машина: **{a['cpu']}**, `{a['platform']}`. Компилятор: **g++ {a['compiler']}**, флаги `{a['compiler_flags']}`. Внутри каждого измерительного прохода проверено единство хеша бинарника и флагов. Параметры модели и поисковые ядра совпадают с предыдущей серией 15 методов. При проверке симулятора устранён пограничный запрет совпадающих клеток текущего состояния и цели при разных курсах. Прерванный предварительный проход сохранён в `results/pre_endpoint_guard_fix` и исключён из анализа; все приведённые времена получены после исправления.''')
    add('Связь с первоисточником проверена по [Hernández, Asín, Baier, «Reusing Previously Found A* Paths for Fast Goal-Directed Navigation in Dynamic Terrain», AAAI 2015, раздел Experimental Results](https://classpages.cselabs.umn.edu/Fall-2021/csci4511-001/misc/HernandezAB15.pdf). Оттуда взяты наборы k/cr и n = k; в статье использованы октильная эвристика, оптимизированный авторский D* Lite и существенно больше начальных задач, включая случайные карты 1000×1000. Здесь геометрическая основа эвристик прежних ядер евклидова, а исходные реализации и карты сохранены для сопоставимости с прежними сериями. Добавленный далее октильный контроль усиливает обычный A*, но не переводит все инкрементальные ядра на октильную эвристику. Это ещё одна причина не трактовать новые времена как репликацию сравнительного рейтинга статьи.')
    add('## Фактическая интенсивность изменений')
    rows=[]
    for (control,name),group in e[e.kind.eq('dynamic')].groupby(['control','map'],sort=True):
        c=next(c for c in contexts.values() if c['control']==control and c['map']==name and c['kind']=='dynamic')
        values=[]
        for cr in [1,5,10,15,20,30]:
            z=next((x for x in contexts.values() if x['control']==control and x['map']==name and x['params'].get('cr')==cr),None)
            if z is None:values.append('—');continue
            values.append(num(z['potential_actual_cr'])+('*' if z['budget_clamped'] else ''))
        rows.append([control,name,num(100*c['truth_density']),*values])
    add(table(['Граф','Карта','Занято, %','cr1','cr5','cr10','cr15','cr20','cr30'],rows))
    add(f"Числа — фактический процент правок **на состоявшуюся фазу**; `*` означает ограничение пулом. Это не число наблюдённых агентом изменений. При высокой видимости агент получает большую долю глобальных изменений; число фаз и реально наблюдённых клеток сохранены для каждого проезда. Полные и обрезанные карты Room/Random/Maze имеют разные плотности и рассматриваются отдельно. Несколько больших номинальных cr могут давать один и тот же ограниченный пакет: такие столбцы физически совпадают и не являются независимыми уровнями интенсивности. Поэтому {m['dynamic_cases']} номинальных динамических конфигураций соответствуют {a['dynamic_physical_cases']} различным физическим конфигурациям с учётом корня. Дополнительно проверено точное совпадение их траекторий, миров и работы поиска при общих приоритетах.")
    add('Далее показана медианная доля глобальных правок, фактически наблюдённых D* lattice, в процентах. Взяты все его попытки с хотя бы одной фазой; значения по cr и двум корням объединены внутри каждого k. Прочерк означает отсутствие измерений или отсутствие фаз. Для car16 каждому измеренному k соответствует одна опорная cr, а для grid8 — все шесть. Сравнивать n в двух моделях как одинаковый геометрический радиус нельзя.')
    observation_rows=[]
    for (control,name),group in e[e.kind.eq('dynamic')&e.method.eq('dstar_lattice')].groupby(['control','map'],sort=True):
        cells=[]
        for k in [2,4,8,16,32,64]:
            z=group[group.k.eq(k)&group.actual_changes.gt(0)];cells.append(num((100*z.observed_changes/z.actual_changes).median()))
        observation_rows.append([control+' / '+name,*cells])
    add(table(['Граф / карта','k2','k4','k8','k16','k32','k64'],observation_rows))
    add('## Раскрытие статической карты: все радиусы и методы')
    add('В каждой ячейке указаны **достижения цели / 2 корня; медиана полного времени поиска в мс** среди успешных проездов. Успех указан первым; медианы с разной полнотой не образуют общий рейтинг. В каждой комбинации радиуса и корня время сначала агрегировано по трём повторам. Полная работа, раскрытая доля карты, длина проезда, p95 и память доступны в таблицах и атласе.')
    for name,group in static.groupby('map',sort=True):
        rows=[]
        for method in METHODS:
            x=group[group.method.eq(method)].set_index('radius');rows.append([LABELS[method],*[f'{int(x.loc[r,"goals"])}/2; {num(1000*x.loc[r,"episode_s"])}' for r in [8,16,32,64]]])
        add('### '+name);add(table(['Метод','r = 8','r = 16','r = 32','r = 64'],rows))
    add('## Динамика: результаты отдельно по каждой карте')
    add('Для каждого метода приведено число целей из **72 конфигураций на grid8-карту** (2 корня × 36 параметров) либо **8 конфигураций на car16-карту** (2 корня × 4 опорных точки), медианное полное время поиска и сумма поиска с сенсором среди успешных проездов, ускорение online относительно D* lattice на общих успешных проездах с фазами, медиана раскрытий и чтений клеток среди успешных проездов. В скобках у ускорения — **число пар**. Ремонт с нулевыми фазами и без последующих вызовов исключён. «Поиск + сенсор» не включает моделирование изменений мира и физическое движение. Это описательная агрегация по разным k/cr, а не доказательство победы на каждом параметре. Полные grid8-матрицы 6×6 и выбранные car16-точки для всех методов приведены в CSV; матрицы ускорений и покрытия — в атласе.')
    for (control,name),group in s[s.kind.eq('dynamic')].groupby(['control','map'],sort=True):
        rows=[];pp=pairs[pairs.control.eq(control)&pairs.kind.eq('dynamic')&pairs['map'].eq(name)&pairs.baseline.eq('dstar_lattice')].set_index('method')
