    atlas.append('Фигуры дополняют основной отчёт `navigation.pdf`. Время и работа поиска рассматриваются вместе с долей целей. В динамических рисунках ускорения рассчитаны на общих успешных проездах с фазами и ненулевым ремонтом у обоих методов; число пар указано в скобках. Серые ячейки не имеют допустимого сравнения, а точка · означает неизмеренное сочетание. Верхние панели показывают все 15 методов, нижние — полные grid8-матрицы либо опорные car16-точки для MD-A* против LBA* reuse и Boundary-Mesh против D* lattice. Значение больше единицы выгодно первому методу.')
    for name in sorted(set(e.loc[e.kind.eq('unknown'),'map'])):
        atlas.append('## Статическое раскрытие / '+name);atlas.append(figure('static_'+name,'Все четыре радиуса и все 15 алгоритмов. Скорость включает конструктор; пары требуют общей достигнутой цели.'))
        atlas.append(figure('trajectories_'+name,'Реальные проезды первого корня при радиусах 8 и 64. Для читаемости показаны LBA* reuse, MD-A* и Boundary-Mesh; полилинии соединяют концы примитивов, а не все клетки их коллизионного следа. Остальные методы полностью представлены в таблицах.'))
    for (control,name),group in e[e.kind.eq('dynamic')].groupby(['control','map'],sort=True):
        atlas.append(f'## Динамика / {control} / {name}')
        scope='с объединением шести cr' if control=='grid8' else 'только для четырёх опорных пар; точки · не измерялись'
        atlas.append(figure('dynamic_'+control+'_'+name,f'Верх: цели и online-ускорение по k=n, {scope}. Низ: отдельные k/cr, MD-A* против LBA* reuse и Boundary-Mesh против D* lattice. В каждой паре требуются общая достигнутая цель, фазы и ненулевой ремонт.'))
    atlas.append('# Предыдущие серии по картам')
    atlas.append('Каждая ячейка: **завершено / конфигураций; полное / online время в мс**. Медианы рассчитаны только по завершённым эпизодам, без объединения временных серий. Для car16 replay оставлен основной заранее заданный срез, остальные чувствительности остаются в исходных CSV. `mission` может иметь ограничения числа шагов; replay «завершено» означает обработку всех снимков, включая доказанное отсутствие пути, и не означает физическое достижение цели. Значения времени памяти взяты только из отдельных проходов.')
    for cohort in ['previous11','contemporary15']:
        for (control,name,mode),group in prior[prior.cohort.eq(cohort)].groupby(['control','map','mode'],sort=True):
            families=sorted(set(group.family));rows=[]
            for method in METHODS:
                z=group[group.method.eq(method)].set_index('family')
                if z.empty:continue
                cells=[]
                for family in families:
                    if family not in z.index:cells.append('—');continue
                    r=z.loc[family];cells.append(f'{int(r.completed)}/{int(r.cases)}; {num(1000*r.episode_s)} / {num(1000*r.online_s)}')
                rows.append([LABELS[method],*cells])
            atlas.append(f'## {cohort} / {control} / {name} / {mode}')
            atlas.append(table(['Метод',*[f.replace('unknown_replay','unknown') for f in families]],rows))
    atlas_header=header('Incremental MeshA*: атлас новых и предыдущих результатов по картам')
    atlas_md=atlas_header+'\n\n'.join(atlas)+'\n'
    atlas_md+='\n\n# Нагрузка наблюдённых изменений\n\n'+figure('work_by_observed_changes','Медианы задержки, раскрытий и чтений по фактическому пакету. На car16 объединены статическое раскрытие и динамика, на grid8 — динамика. Полные группы всех карт и 15 методов — work_by_observed_changes.csv; группы включают остановки, зависят от собственных траекторий и не являются парным контролем.')+'\n\n'+control_body.read_text()
    atlas_md=(atlas_header+literal_stars(atlas_md[len(atlas_header):])).rstrip()+'\n'
    (DEST/'navigation_by_map.md').write_text(atlas_md)
    if make_pdf:pdf(main,'navigation.pdf');pdf(atlas_md,'navigation_by_map.pdf')
    provenance=dict(status='passed',source_sha256=digest(Path(__file__)),analysis_sha256=digest(ad/'analysis.json'),figures_manifest_sha256=digest(ad/'figures.json'),
                    body_sha256=digest(DEST/'navigation_body.md'),markdown_sha256=digest(DEST/'navigation.md'),atlas_markdown_sha256=digest(DEST/'navigation_by_map.md'),
                    layout_sha256=digest(DEST/'layout.tex'),controls_directory=str(controls_directory.relative_to(ROOT)),controls_analysis_sha256=digest(control_analysis))
    if make_pdf:provenance.update(pdf_sha256=digest(DEST/'navigation.pdf'),atlas_pdf_sha256=digest(DEST/'navigation_by_map.pdf'))
    (ad/'report_provenance.json').write_text(json.dumps(provenance,indent=2)+'\n');print('Reports written:',DEST/'navigation.md',DEST/'navigation_by_map.md')

